<?php
namespace App\Http\Controllers; use App\Models\Inspection; use Illuminate\Http\Request; class InspectionController extends Controller { public function index(){return Inspection::with('facility')->get();} public function store(Request $r){$data=$r->validate(['facility_id'=>'required|exists:facilities,id','inspection_date'=>'required|date','cleanliness_score'=>'nullable|numeric|between:0,10','odor_score'=>'nullable|numeric|between:0,10','waste_level'=>'nullable|numeric|between:0,10','status'=>'required|in:Good,Needs Attention,Poor','remarks'=>'nullable|string']);return response()->json(Inspection::create($data),201);} public function show(Inspection $inspection){return $inspection->load('facility');} public function update(Request $r,Inspection $inspection){$data=$r->validate(['facility_id'=>'required|exists:facilities,id','inspection_date'=>'required|date','cleanliness_score'=>'nullable|numeric|between:0,10','odor_score'=>'nullable|numeric|between:0,10','waste_level'=>'nullable|numeric|between:0,10','status'=>'required|in:Good,Needs Attention,Poor','remarks'=>'nullable|string']);$inspection->update($data);return $inspection;} public function destroy(Inspection $inspection){$inspection->delete();return response()->noContent();} }
